DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT114-S2-Q23$batch12$ AND q.stimulus=$batch12$Reviewer: Although finalism—the view that there are purposes in nature—has been universally rejected, this book launches another attack on that view. Its arguments are based on a complete misunderstanding of the operation of pure chance in nature and so it fails as a critique of finalism. Finalism, therefore, is clearly more plausible than people have thought.$batch12$ AND q.prompt=$batch12$Which one of the following is most closely parallel in its flawed reasoning to the flawed reasoning in the reviewer's argument?$batch12$ AND q.correct_choice=$batch12$C$batch12$) THEN RAISE EXCEPTION 'Question changed: PT114-S2-Q23'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT114-S2-Q23$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT114-S2-Q23'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT114-S2-Q23$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$Finalism is more plausible than people thought.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$Finalism is universally rejected. A new book attacks it, but the book's arguments are confused.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$One bad argument against a view does nothing to support the view. The reviewer treats a failed attack as evidence for a widely rejected position.$batch12$), (3, $batch12$Goal$batch12$, $batch12$A rejected view; one attack on it fails; so the view is more plausible than believed.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT114-S2-Q23$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
